style.css:
@-moz-document domain("roblox.com") {
@font-face {
    font-family: 'Rubik Mono One';
    src: url('https://fonts.gstatic.com/s/rubikmonoone/v21/UqyJK8kPP3hjw6ANTdfRk9YS.woff2') format('woff2');
  }

  body, html {
    background: linear-gradient(to bottom, #4e342e, #3e2723) !important;
    font-family: 'Rubik Mono One', sans-serif !important;
    color: #fbe9e7 !important;
    scroll-behavior: smooth;
    transition: background 0.3s ease;
  }

  body::before {
    content: "TUNG TUNG TUNG SAHUR!";
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    background-color: #6d4c41;
    color: #fff3e0;
    font-size: 14px;
    text-align: center;
    padding: 4px;
    z-index: 9999;
    animation: sahurPulse 2s infinite ease-in-out;
  }

  @keyframes sahurPulse {
    0% { letter-spacing: 1px; }
    50% { letter-spacing: 3px; }
    100% { letter-spacing: 1px; }
  }

  .navbar, .header, .top-nav, footer {
    background-color: #5d4037 !important;
    border-bottom: 1px solid #795548;
  }

  a, button, .btn-primary, .btn-secondary {
    background-color: #8d6e63 !important;
    color: #fff3e0 !important;
    border: none !important;
    border-radius: 6px !important;
    padding: 6px 12px !important;
    transition: background-color 0.3s ease;
  }

  a:hover, button:hover {
    background-color: #a1887f !important;
  }

  .container, .section, .content, .game-card-container, .game-card {
    background-color: rgba(255, 248, 225, 0.03) !important;
    border-radius: 6px;
    box-shadow: none !important;
    padding: 10px !important;
    margin-bottom: 8px;
  }

  .game-card-container, .game-tile {
    max-width: 100% !important;
    margin: 0 auto !important;
  }

  .game-card {
    background-color: #3e2723 !important;
    border: 1px solid #4e342e;
    transition: transform 0.2s ease-in-out;
  }

  .game-card:hover {
    transform: scale(1.01);
  }

  input, select, textarea {
    background-color: #4e342e !important;
    color: #fff3e0 !important;
    border: 1px solid #6d4c41 !important;
    border-radius: 4px;
  }

  input:focus, select:focus, textarea:focus {
    border-color: #a1887f !important;
    outline: none !important;
  }

  ::-webkit-scrollbar {
    width: 6px;
  }

  ::-webkit-scrollbar-track {
    background: transparent;
  }

  ::-webkit-scrollbar-thumb {
    background-color: #8d6e63;
    border-radius: 10px;
  }

  footer {
    color: #d7ccc8;
    font-size: 11px;
    text-align: center;
    padding: 10px;
  }

  #navbar-logo img {
    filter: brightness(1.2) contrast(1.1);
  }

  #nav-settings, #nav-home, #nav-profile {
    animation: none !important;
  }
}
